package main

import (
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"slices"
	"strings"
)

// A "utility" module with the one function we want, next to one we don't;
// an app that depends on it; and the same app with that function copied in.
var files = map[string]string{
	"strutil/go.mod": "module example.com/strutil\n\ngo 1.27\n",
	"strutil/strutil.go": `package strutil

import "net/http"

func Truncate(s string, n int) string {
	if r := []rune(s); len(r) > n {
		return string(r[:n]) + "…"
	}
	return s
}

func Fetch(url string) (*http.Response, error) { return http.Get(url) }
`,
	"app-dep/go.mod": "module example.com/app\n\ngo 1.27\n\nrequire example.com/strutil v1.0.0\n\nreplace example.com/strutil => ../strutil\n",
	"app-dep/main.go": `package main

import (
	"fmt"

	"example.com/strutil"
)

func main() { fmt.Println(strutil.Truncate("Merhaba dünya, nasılsın?", 12)) }
`,
	"app-copy/go.mod": "module example.com/app\n\ngo 1.27\n",
	"app-copy/main.go": `package main

import "fmt"

// truncate is copied from example.com/strutil v1.0.0 (MIT), minus the dependency.
func truncate(s string, n int) string {
	if r := []rune(s); len(r) > n {
		return string(r[:n]) + "…"
	}
	return s
}

func main() { fmt.Println(truncate("Merhaba dünya, nasılsın?", 12)) }
`,
}

func main() {
	for name, body := range files { // the runner starts in a fresh directory
		os.MkdirAll(filepath.Dir(name), 0o755) // if this fails, WriteFile fails too
		if err := os.WriteFile(name, []byte(body), 0o644); err != nil {
			panic(err)
		}
	}
	for _, app := range []string{"app-dep", "app-copy"} {
		// Everything go build would compile. The target is pinned, so the
		// count is the same on every machine.
		cmd := exec.Command("go", "list", "-deps", "./...")
		cmd.Dir = app
		cmd.Env = append(os.Environ(), "GOOS=linux", "GOARCH=amd64", "CGO_ENABLED=0")
		out, err := cmd.CombinedOutput()
		if err != nil {
			panic(fmt.Sprintf("%v\n%s", err, out))
		}
		deps := strings.Fields(string(out))
		fmt.Printf("%-9s %3d packages, net/http %v, crypto/tls %v\n", app+":",
			len(deps), slices.Contains(deps, "net/http"), slices.Contains(deps, "crypto/tls"))
	}
}

files.examples/02_stdlib_first.go:
package main

import (
	"cmp"
	"fmt"
	"maps"
	"slices"
	"strings"
)

type Run struct {
	Lesson string
	Millis int
}

func main() {
	runs := []Run{
		{"go.basics.defer", 420}, {"sql.joins.lateral", 95},
		{"go.basics.defer", 380}, {"ts.react.query", 1210},
	}

	// Group by key: a map and a loop, no GroupBy helper needed.
	byLesson := map[string][]int{}
	for _, r := range runs {
		byLesson[r.Lesson] = append(byLesson[r.Lesson], r.Millis)
	}
	for _, id := range slices.Sorted(maps.Keys(byLesson)) { // Go 1.23
		fmt.Println(id, byLesson[id], "max:", slices.Max(byLesson[id]))
	}

	// Sort by one field, then another: cmp.Or picks the first non-zero result.
	slices.SortFunc(runs, func(a, b Run) int {
		return cmp.Or(cmp.Compare(b.Millis, a.Millis), strings.Compare(a.Lesson, b.Lesson))
	})
	fmt.Println("slowest:", runs[0].Lesson)

	// Unique values: sort, then drop adjacent duplicates.
	var ids []string
	for _, r := range runs {
		ids = append(ids, r.Lesson)
	}
	slices.Sort(ids)
	ids = slices.Compact(ids)
	fmt.Println("unique:", ids)

	// Batches of two (Go 1.23).
	for batch := range slices.Chunk(ids, 2) {
		fmt.Println("batch:", batch)
	}

	// Split once without a regexp; built-in min and max (Go 1.21).
	track, rest, _ := strings.Cut("go.basics.defer", ".")
	fmt.Println(track, "|", rest, "| min:", min(3, 1, 2), "| default:", cmp.Or("", "unnamed"))
}

files.examples/03_mutex_or_channel.go:
package main

import (
	"fmt"
	"maps"
	"sync"
)

// "Share memory by communicating": one goroutine owns the counts, and
// everyone else sends it messages.
type ChanCounter struct {
	incs  chan string
	reads chan chan map[string]int
}

func NewChanCounter() *ChanCounter {
	c := &ChanCounter{incs: make(chan string), reads: make(chan chan map[string]int)}
	go func() {
		counts := map[string]int{}
		for {
			select {
			case key := <-c.incs:
				counts[key]++
			case reply := <-c.reads:
				reply <- maps.Clone(counts)
			}
		}
	}()
	return c
}

func (c *ChanCounter) Inc(key string) { c.incs <- key }

func (c *ChanCounter) Snapshot() map[string]int {
	reply := make(chan map[string]int)
	c.reads <- reply
	return <-reply
}

// "Mutexes serialize": the same counter, guarded state instead of an owner.
type MutexCounter struct {
	mu     sync.Mutex
	counts map[string]int
}

func (c *MutexCounter) Inc(key string) {
	c.mu.Lock()
	defer c.mu.Unlock()
	if c.counts == nil {
		c.counts = map[string]int{}
	}
	c.counts[key]++
}

func (c *MutexCounter) Snapshot() map[string]int {
	c.mu.Lock()
	defer c.mu.Unlock()
	return maps.Clone(c.counts) // a copy: callers must not share our map
}

func main() {
	type counter interface {
		Inc(string)
		Snapshot() map[string]int
	}
	for _, c := range []counter{NewChanCounter(), &MutexCounter{}} {
		var wg sync.WaitGroup
		for i := range 1000 {
			wg.Go(func() { c.Inc([]string{"go", "sql"}[i%2]) })
		}
		wg.Wait()
		fmt.Printf("%T: %v\n", c, c.Snapshot())
	}
}
